import os,json,html,re,shutil
from pathlib import Path
D=Path('dist'); D.mkdir(exist_ok=True)
BASE=os.environ.get('SITE_URL','https://tecur-automotive-studio.michellinoamah.chatgpt.site').rstrip('/')
PUBLIC=os.environ.get('PUBLIC_SITE')=='1'
catalog=json.loads(Path('data/catalog.json').read_text())
catalog=[c for c in catalog if c.get('status')=='published']
for c in catalog:
 if not re.fullmatch(r'[a-zA-Z0-9_-]{1,100}',c.get('id','')): raise ValueError('Invalid listing id')
# Clear old generated routes so archived listings are not left public after a rebuild.
for folder in D.iterdir():
 if folder.is_dir() and folder.name not in ['assets']: shutil.rmtree(folder)
E=lambda x:html.escape(str(x),quote=True)
nav=[('/services/','Services'),('/parts/','Parts & listings'),('/garage/','My Toyota'),('/journal/','Car guides'),('/before-you-pay/','Before you pay'),('/about/','About')]
services=[('diagnostics','Engine diagnostics','We check warning lights, rough running and loss of power.','Warning lights, rough running or a loss of power? Start with a structured inspection, fault-code reading and a discussion of your vehicle’s history. Codes are clues, not a final diagnosis.','Diagnostic scan and fault investigation','Describe the symptom, when it started and any recent repairs.','A technician can explain the findings and recommend the next checks before repair work is approved.'),('electrical','Electrical & starting','We check the battery, starter and charging system.','Slow cranking, repeated battery problems and charging warnings need a system check. We investigate the battery, charging circuit and starter operation before recommending a replacement.','Battery, alternator and starter investigation','Share whether the engine cranks, clicks or stays silent.','Fitment is checked against your vehicle specification before a component is ordered.'),('cooling','Cooling & air conditioning','Ask about a hot engine or an AC that blows warm air.','Engine cooling and cabin air conditioning do different jobs. We help identify whether your concern relates to airflow, temperature control, coolant circulation or the AC system.','Cooling-system and AC inspection','Tell us whether the temperature rises at idle or while driving.','If the engine is overheating, stop safely and let it cool. Never open a hot coolant cap.'),('brakes','Brakes & suspension','Tell us about noisy brakes, shaking or uneven tyre wear.','Squeals, vibration, uneven tyre wear and a change in pedal feel deserve a proper inspection. We examine the affected system before discussing repair options.','Brake and suspension inspection','Describe where you hear the sound and what the car is doing.','A soft pedal or reduced braking ability needs urgent professional attention; do not keep driving.'),('maintenance','Planned maintenance','Plan oil changes, filter changes and routine checks.','Oil, filters, belts and routine checks should follow your Toyota’s manual and operating conditions. We help you plan maintenance around the actual vehicle, rather than a generic interval.','Vehicle-specific routine maintenance','Bring your last service record, mileage and vehicle year.','Ask for a written breakdown of the proposed work and parts before approval.'),('mobile','Mobile Toyota care','Ask if a mechanic can check your Toyota at home or work.','Request a visit at your home or workplace in Lekki. Share the location and symptoms first so our team can assess whether the job is suitable for mobile service.','On-site assessment and suitable repairs','Provide a safe parking area and accurate location.','Availability, arrival time and mobile suitability are confirmed by our team. Some jobs require the workshop.')]
def picture(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="/assets/{name}.webp" srcset="/assets/{name}-800.webp 800w, /assets/{name}.webp 1400w" sizes="(max-width:760px) 100vw, 50vw" width="1400" height="900" alt="{alt}" loading="{"eager" if eager else "lazy"}" {"fetchpriority=high" if eager else ""}>'
def listingpic(c):
 src=c.get('image','/assets/detail.webp')
 if not (src.startswith('https://') or re.fullmatch(r'/assets/[a-zA-Z0-9_.-]+',src)): src='/assets/detail.webp'
 return '<img src="'+E(src)+'" alt="'+E(c['title'])+'" width="800" height="530" loading="lazy">'
def link(url,text,kind='btn'):return f'<a class="{kind}" href="{url}">{text} <span aria-hidden="true">↗</span></a>'
def head(kicker,title,desc):return f'<section class="page-head"><div class="shell"><div class="breadcrumb"><a href="/">Home</a> / {kicker}</div><div class="eyebrow">{kicker}</div><h1>{title}</h1><p>{desc}</p></div></section>'
def banner():return '<section class="banner"><div class="shell"><div><div class="eyebrow">A better relationship with your Toyota</div><h2>Good care.<br>Great journeys.</h2></div>'+link('/book/','Let’s talk about your Toyota')+'</div></section>'
paths=[]
def page(path,title,desc,body,extra='',schema=None):
 if path=='/admin/':
  body=body.replace('</aside>', '<button data-tab="posts">▤ Blog posts</button><button data-tab="popups">◈ Pop-ups</button></aside>')
  body=body.replace('<p id="admin-status"', '<section data-panel="posts" hidden><div class="section-head"><h3>Blog posts</h3><button class="btn" id="add-post">+ Write or import a post</button></div><div id="manage-posts"></div><button class="btn ghost" id="export-content">Export blog & pop-up content</button></section><section data-panel="popups" hidden><div class="section-head"><h3>Pop-up campaigns</h3><button class="btn" id="add-popup">+ Create pop-up</button></div><div id="manage-popups"></div></section><p id="admin-status"')
  if 'id="admin-workspace"' in body: body+=Path('scripts/templates/addons.html').read_text()
  body=body.replace('Staff-entered follow-ups from calls and WhatsApp. This does not automatically import messages.', 'Direct website enquiries and staff-entered follow-ups. WhatsApp messages are handled in WhatsApp.')
