page('/book/','Book Toyota service in Lekki','Prepare a Toyota service or parts enquiry for Tecur Automotive. Choose workshop or mobile service and contact our team through WhatsApp.',head('Let’s get you moving','REQUEST A SERVICE<br>OR A SPARE PART.','Tell us a little about your Toyota. Review your request, then open WhatsApp to send it directly to the team.')+'''<section class="section" style="padding-top:15px"><div class="shell split-form"><div><div class="eyebrow">A simple, human process</div><h2>HOW TO SEND<br>YOUR REQUEST.</h2><ul class="number-list"><li><span>01</span>Share your vehicle and what you need.</li><li><span>02</span>Review your enquiry before sending.</li><li><span>03</span>Our team confirms the next steps and availability.</li></ul><div class="contact-line"><small>Prefer a conversation?</small><a href="tel:+2347085990547">+234 708 599 0547 ↗</a></div><p style="margin-top:22px;font-size:12px">An enquiry does not reserve a time slot. We’ll confirm the appointment with you.</p></div><form id="booking-form" class="form-box"><div class="step-label">YOUR ENQUIRY</div><div class="form-row"><label>Your name<input required name="name" autocomplete="name" maxlength="100" placeholder="Full name"></label><label>Phone number<input required name="phone" type="tel" autocomplete="tel" maxlength="25" placeholder="Your contact number"></label></div><div class="form-row"><label>Toyota model<select required name="model">'''+models+'''</select></label><label>Model year<input required name="year" type="number" min="1980" max="2027" placeholder="e.g. 2017"></label></div><div class="form-row"><label>What do you need?<select name="service"><option value="diagnostics">Engine diagnostics</option><option value="electrical">Electrical & starting</option><option value="cooling">Cooling & AC</option><option value="brakes">Brakes & suspension</option><option value="maintenance">Planned maintenance</option><option value="parts">Parts enquiry</option></select></label><label>Where suits you?<select name="mode"><option>Workshop visit</option><option>Mobile service request</option></select></label></div><label>Preferred date (subject to confirmation)<input name="date" type="date"></label><label>Your location<input name="location" maxlength="160" placeholder="Area or nearest landmark"></label><label>What have you noticed?<textarea required name="message" rows="4" maxlength="2000" placeholder="When did it start? What does it sound or feel like?"></textarea></label><label style="display:flex;gap:10px;align-items:start"><input type="checkbox" required style="width:18px;margin:3px 0">I agree to share these details with Tecur via WhatsApp. <a class="textlink" href="/privacy/">Privacy</a></label><button class="btn" type="submit">Review my request ↗</button><div id="booking-review" class="result" aria-live="polite"></div></form></div></section>''')
page('/garage/','My Toyota — service planner & ownership tools','Save your Toyota details on this device, prepare a service brief and create a maintenance checklist. Practical ownership tools from Tecur Automotive.',head('Your personal pit stop','MY TOYOTA<br>PLANNER.','Save your car details, prepare for a service and estimate fuel costs. Your details and checklist stay in this browser.')+'''<section class="section" style="padding-top:15px"><div class="shell grid two"><form id="garage-form" class="tool-panel"><div class="step-label">01 / CAR DETAILS</div><h3>Save your car details.</h3><p>Save your model once. Carry it into your next service enquiry.</p><label>Toyota model<select name="model" required>'''+models+'''</select></label><div class="form-row"><label>Model year<input name="year" required type="number" min="1980" max="2027"></label><label>Mileage on your dashboard (km)<input name="mileage" required type="number" min="0" max="2000000"></label></div><label>Last service date<input name="lastService" type="date"></label><div class="inline-actions"><button class="btn">Save my Toyota</button><button type="button" class="btn ghost" id="garage-clear">Clear</button></div><p id="garage-status" class="form-status" role="status"></p></form><div class="tool-panel"><div class="step-label">02 / BEFORE THE NEXT JOURNEY</div><h3>Before your visit</h3><div class="checklist" id="checklist">'''+''.join(f'<label><input type="checkbox" data-check="{i}">{s}</label>' for i,s in enumerate(['Check tyres when cold against the vehicle placard','Look for new fluid leaks beneath the car','Check lights and windscreen visibility','Review service history and owner’s manual','Note any new sound or warning light']))+'''</div><p id="check-progress" style="font-size:12px;margin-top:18px">0 of 5 checked</p><progress max="5" value="0" id="check-meter"></progress><small class="muted">This checklist does not replace a professional inspection.</small></div><div class="tool-panel"><div class="step-label">03 / OWNERSHIP BUDGET EXPLORER</div><h3>Know your running costs.</h3><p>An editable planning estimate. It is not a service or fuel quotation.</p><div class="form-row"><label>Monthly distance (km)<input id="cost-distance" type="number" min="0" max="50000" value="1000"></label><label>Consumption (L/100km)<input id="cost-economy" type="number" min="1" max="50" step="0.1" value="10"></label><label>Fuel price (₦/litre)<input id="cost-fuel" type="number" min="0" max="10000" value="1000"></label><label>Maintenance reserve (₦/month)<input id="cost-reserve" type="number" min="0" max="10000000" value="20000"></label></div><h3 id="cost-total" aria-live="polite">₦120,000 / month</h3><small class="muted">Illustrative inputs. Excludes insurance, finance, depreciation and unexpected repairs.</small></div><div class="tool-panel"><div class="step-label">04 / SHORTLIST → SERVICE BRIEF</div><h3>Less explaining.<br>More understanding.</h3><p>Save parts in the catalogue, then use your saved car details to prefill a booking. No account needed.</p><div class="inline-actions">'''+link('/parts/','Find your parts')+link('/book/','Prepare an enquiry','btn ghost')+'</div></div></div></section>')
page('/about/','About Tecur — Toyota specialists in Lekki','Meet Tecur Automotive, an independent Toyota-focused service and parts business at 2 Lawal St, Lekki Peninsula II, Lagos.',head('The Tecur approach','ABOUT TECUR<br>AUTOMOTIVE.','We are an independent Toyota workshop in Lekki, Lagos. We help drivers with repairs, servicing and spare parts.')+'<section class="section"><div class="shell feature">'+picture('workshop','Illustrative technician working beneath an open bonnet')+'<div class="prose"><div class="eyebrow">Independent Toyota expertise</div><h2>OUR WORKSHOP<br>IN LEKKI.</h2><p>Tecur Automotive focuses on Toyota service, repair and parts enquiries in Lekki, Lagos. From diagnostics and electrical work to cooling systems and planned maintenance, our approach starts with listening and inspection.</p><p>We offer workshop visits and mobile service for suitable jobs. Before work begins, we discuss the findings and the proposed next steps so you can make an informed decision.</p><p>Our workshop is at 2 Lawal St, Lekki Peninsula II. We serve owners around Jakande, Agungi, Osapa, Chevron and VGC.</p>'+link('/contact/','Come say hello','textlink')+'</div></div></section>'+banner())
page('/contact/','Contact Tecur Automotive in Lekki, Lagos','Visit 2 Lawal St, Lekki Peninsula II, Lagos. Call +234 708 599 0547 or contact Tecur Automotive for Toyota service and parts.',head('Find your specialists','CONTACT<br>OUR TEAM.','A question about a part, a sound you can’t place, or a service to plan? Start a conversation.')+'<section class="section"><div class="shell grid two"><div><div class="contact-line"><small>Visit the workshop</small><h3>2 Lawal St, Lekki Peninsula II<br>Lagos 106104, Nigeria</h3></div><div class="contact-line"><small>Call the team</small><a href="tel:+2347085990547">+234 708 599 0547 ↗</a></div><div class="contact-line"><small>WhatsApp</small><a href="https://wa.me/2347043966114" target="_blank" rel="noopener">+234 704 396 6114 ↗</a></div><div class="contact-line"><small>Email</small><a href="mailto:tecurautomotive@gmail.com" style="font-size:17px">tecurautomotive@gmail.com ↗</a></div></div><div class="tool-panel"><div class="eyebrow">Plan your visit</div><h3>WORKSHOP HOURS.</h3><p>Monday–Saturday · 8:00 AM–6:00 PM<br>Contact us before travelling to confirm availability.</p>'+link('https://www.google.com/maps/search/?api=1&query=2+Lawal+St+Lekki+Peninsula+II+Lagos','Open directions')+'<h3 style="margin-top:35px">Need us to come to you?</h3><p>Ask about mobile service in Jakande, Agungi, Osapa, Chevron and VGC. Suitability and arrival time depend on the job.</p>'+link('/book/','Request mobile care','textlink')+'</div></div></section>')
articles=[('before-you-buy-toyota-parts','Before you buy a Toyota part','PARTS / 4 MIN READ','Two Toyotas with the same model name can use different parts. Here is what to check before paying.',[('Start with the actual vehicle','Two cars with the same model name can use different components. Record the model year, engine and trim where known. A VIN or existing part number gives the team a more useful starting point.'),('Describe the fault before choosing the fix','A car that will not start does not automatically need a starter motor. Battery condition, cables, connections and other systems can produce similar symptoms. Share the symptoms and ask what checks are needed.'),('Ask what the quotation includes','Confirm the part specification, condition, availability, labour and any applicable warranty terms. Ask for those terms before payment. Keep your receipt and the agreed specification.'),('Ask us to check that the part fits','Use our catalogue as a conversation starter. A listing or category does not establish compatibility with your car. Bring the old part number or vehicle details when requesting a quote.')]),('prepare-for-toyota-service','A better Toyota service starts before you arrive','OWNERSHIP / 3 MIN READ','Tell the mechanic when the problem started and what you noticed.',[('Write down when it happens','Is the engine hot or cold? Are you braking, turning, idling or accelerating? Note the conditions and how long the symptom lasts. Do not drive a vehicle with unsafe braking or overheating simply to reproduce a problem.'),('Bring your service history','Recent repairs, replaced parts and the date of the last service can help the investigation. Bring available records and your owner’s manual. If something changed immediately after previous work, mention it.'),('Agree the scope first','Ask what the initial inspection includes, whether there is a diagnostic fee and how additional work will be approved. An appointment request is not a confirmed booking until the workshop responds.'),('Keep the handover useful','Remove personal valuables and leave a reliable contact number. Ask for a written explanation of completed work and the next recommended checks.')]),('mobile-or-workshop','Mobile service or workshop visit?','LEKKI LIFE / 3 MIN READ','Choose the setting that suits the job, not just the distance.',[('Start with an honest description','Tell the team whether the vehicle starts, moves and stops safely. Give an accurate location and describe access to the vehicle. The technician can then assess whether a mobile visit is appropriate.'),('Prepare a suitable working area','A level, accessible parking area away from moving traffic is more useful than a roadside location. The team must decide whether the work can be performed safely with the available space and equipment.'),('Some jobs need the workshop','Repairs requiring lifting equipment, extended dismantling or specialist facilities may need a workshop visit. A mobile assessment can still help establish the next step, subject to availability.'),('Confirm the details','Ask about the visit charge, expected scope, parts and arrival window. Do not assume that a requested time is confirmed. If a vehicle cannot be moved safely, ask about appropriate recovery arrangements.')])]
page('/journal/','Toyota ownership guides & service advice','Practical guides on Toyota parts, service preparation and mobile care for owners in Lekki, Lagos.',head('Car guides','GUIDES FOR<br>TOYOTA OWNERS.','Clear, practical notes for Toyota owners. No jargon. Just useful preparation for the road ahead.')+'<section class="section"><div class="shell grid three">'+''.join('<a class="journal-card" href="/journal/'+slug+'/"><span class="tag">'+meta+'</span><h3>'+title+'</h3><p>'+intro+'</p><span class="textlink">Read the guide ↗</span></a>' for slug,title,meta,intro,paras in articles)+'</div></section>')
for slug,title,meta,intro,paras in articles:
 page('/journal/'+slug+'/',title,intro,head('Car guides',title,intro)+'<section class="section"><article class="shell prose"><span class="tag">'+meta+'</span>'+''.join('<h2>'+h+'</h2><p>'+p+'</p>' for h,p in paras)+'<div class="inline-actions">'+link('/book/','Talk to the team')+link('/journal/','More guides','textlink')+'</div></article></section>')
page('/privacy/','Privacy & service terms','How Tecur Automotive handles your enquiry, photos and optional location, and what to expect when requesting parts or service.',head('Privacy & service terms','YOUR PRIVACY<br>AND SERVICE TERMS.','Simple information about your privacy, your choices and our services.')+Path('scripts/templates/customer-privacy.html').read_text())
